    return [list(reversed([grid[r][c] for r in range(len(grid))])) for c in range(len(grid[0])-1,-1,-1)]

def rotate_180(grid):
    return [list(reversed([row[c] for row in reversed(grid)])) for row in grid]

def flip_v(grid):
    return [list(row) for row in reversed(grid)]

def flip_h(grid):
    return [[row[::-1] for row in grid]]

